import bisect, hashlib

def h(s: str) -> int:
    return int(hashlib.md5(s.encode()).hexdigest(), 16) % (2**32)

class Ring:
    def __init__(self, nodes, vnodes=100):
        self.ring = sorted((h(f"{n}#{i}"), n) for n in nodes for i in range(vnodes))
        self.keys = [k for k, _ in self.ring]

    def get(self, key: str) -> str:
        i = bisect.bisect(self.keys, h(key)) % len(self.keys)  # 顺时针第一个
        return self.ring[i][1]

keys = [f"user:{i}" for i in range(10000)]
r3 = Ring(["A", "B", "C"])
r4 = Ring(["A", "B", "C", "D"])
moved = sum(r3.get(k) != r4.get(k) for k in keys)
print(f"新增一个节点后迁移比例: {moved / len(keys):.1%}")   # 约 25%，取模哈希约 75%

import hashlib, math

class Bloom:
    def __init__(self, n: int, p: float):
        self.m = math.ceil(-n * math.log(p) / (math.log(2) ** 2))  # 位数
        self.k = max(1, round(self.m / n * math.log(2)))           # 哈希个数
        self.bits = bytearray((self.m + 7) // 8)

    def _idx(self, item: str):
        d = hashlib.sha256(item.encode()).digest()
        a, b = int.from_bytes(d[:8], "big"), int.from_bytes(d[8:16], "big")
        return [(a + i * b) % self.m for i in range(self.k)]       # 双重哈希

    def add(self, item: str):
        for i in self._idx(item):
            self.bits[i // 8] |= 1 << (i % 8)

    def __contains__(self, item: str) -> bool:
        return all(self.bits[i // 8] >> (i % 8) & 1 for i in self._idx(item))

bf = Bloom(n=1_000_000, p=0.01)     # 百万元素、1% 误判率 → 约 1.2MB、k=7
bf.add("user:42")
print("user:42" in bf, "user:43" in bf, bf.m, bf.k)

